@st.cache_resource
def demo_index():
    """class index -> list of demo sample indices, best-predicted first (for reference clips and scripted demos)."""
    if DEMO_D is None:
        return {}
    pred = get_predictor("onnx-cpu" if ONNX.exists() else "torch-cpu")
    out = {}
    for k, (lab, b) in enumerate(zip(DEMO_D["labels"], DEMO_D["base"])):
        cov = float((np.abs(b).sum(1) > 0).mean())   # prefer clips where the hands are tracked throughout
        out.setdefault(int(lab), []).append((float(pred.predict(b)[lab]) * (0.3 + 0.7 * cov), k))
    return {c: [k for _, k in sorted(v, reverse=True)] for c, v in out.items()}


# ---------------------------------------------------------------------------------------------- storage
class Store:
    """PostgreSQL when reachable (the notebook's schema), else a local SQLite file. Writes go through a background
    thread so a slow or dead database can never stall the camera loop."""

    LITE_SCHEMA = """
    CREATE TABLE IF NOT EXISTS app_sessions (id TEXT PRIMARY KEY, mode TEXT, engine TEXT, device TEXT,
        started_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS predictions (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, source TEXT, gloss TEXT,
        confidence REAL, top5 TEXT, accepted INTEGER, user_corrected INTEGER DEFAULT 0, truth TEXT, n_frames INTEGER,
        landmark_ms REAL, model_ms REAL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS transcripts (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, text TEXT, language TEXT,
        spoken INTEGER DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    CREATE TABLE IF NOT EXISTS practice_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, sign_key TEXT, gloss TEXT, score REAL,
        success INTEGER, source TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
    """

    def __init__(self):
        self.kind, self.pool, self.vocab = None, None, {}
        self.q = queue.Queue()
        if os.environ.get("PGPASSWORD") or os.environ.get("PGHOST"):
            try:
                self.pool = isl_core.make_pool()
                with self.pool.connection(timeout=3) as c:
                    c.execute("SELECT 1")
                    c.execute("CREATE TABLE IF NOT EXISTS practice_attempts (id bigserial PRIMARY KEY, sign_key text NOT NULL, "
                              "gloss text NOT NULL, score real, success boolean, source text, created_at timestamptz NOT NULL DEFAULT now())")
                    self.vocab = dict(c.execute("SELECT class_index, id FROM vocabulary").fetchall())
                self.kind = "postgres"
            except Exception as e:
                log(f"PostgreSQL unavailable ({str(e)[:120]}); using SQLite")
                try:
                    self.pool.close()
                except Exception:
                    pass
                self.pool = None
        if self.kind is None:
            (ROOT / "data").mkdir(exist_ok=True)
            self.path = str(ROOT / "data" / "signsetu.db")
            with sqlite3.connect(self.path) as c:
                c.executescript(self.LITE_SCHEMA)
            self.kind = "sqlite"
        threading.Thread(target=self._writer, daemon=True).start()

    @property
    def label(self):
        return "PostgreSQL" if self.kind == "postgres" else "SQLite (local)"

    def _writer(self):
        lite = sqlite3.connect(self.path, check_same_thread=False) if self.kind == "sqlite" else None
        while True:
            sql, params = self.q.get()
            try:
                if lite is not None:
                    lite.execute(sql, params); lite.commit()
                else:
                    with self.pool.connection(timeout=3) as c:
                        c.execute(sql, params)
            except Exception as e:
                log(f"DB write failed: {str(e)[:200]}")

    def write(self, pg_sql, lite_sql, params):
        self.q.put((pg_sql if self.kind == "postgres" else lite_sql, params))

    def read(self, pg_sql, lite_sql, params=()):
        try:
            if self.kind == "postgres":
                with self.pool.connection(timeout=3) as c:
                    return c.execute(pg_sql, params).fetchall()
            with sqlite3.connect(self.path) as c:
                return c.execute(lite_sql, params).fetchall()
        except Exception as e:
            log(f"DB read failed: {str(e)[:200]}")
            return None


@st.cache_resource
def get_store():
    return Store()


