def ensure_session(mode, engine, device):
    key = f"sid_{mode}"
    if key not in st.session_state:
        sid = str(uuid.uuid4())
        st.session_state[key] = sid
        STORE.write("INSERT INTO app_sessions (id, mode, engine, device) VALUES (%s,%s,%s,%s)",
                    "INSERT INTO app_sessions (id, mode, engine, device) VALUES (?,?,?,?)", (sid, mode, engine, device))
    return st.session_state[key]


def log_prediction(source, probs, accepted, n_frames, lm_ms, model_ms, corrected=False, truth=None):
    sid = ensure_session(source, ENG_KEY[engine_label], DEV_LABEL)
    order = np.argsort(-probs)[:5]
    top5 = json.dumps([{"gloss": GLOSS[i], "prob": round(float(probs[i]), 4)} for i in order])
    t = int(order[0])
    if STORE.kind == "postgres":
        STORE.write("INSERT INTO predictions (session_id, source, top1_vocab_id, confidence, top5, accepted, user_corrected, "
                    "ground_truth_vocab_id, n_frames, landmark_ms, model_ms) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)", None,
                    (sid, source, STORE.vocab.get(t), float(probs[t]), top5, bool(accepted), bool(corrected),
                     STORE.vocab.get(int(truth)) if truth is not None else None, int(n_frames), float(lm_ms), float(model_ms)))
    else:
        STORE.write(None, "INSERT INTO predictions (session_id, source, gloss, confidence, top5, accepted, user_corrected, truth, "
                    "n_frames, landmark_ms, model_ms) VALUES (?,?,?,?,?,?,?,?,?,?,?)",
                    (sid, source, GLOSS[t], float(probs[t]), top5, int(bool(accepted)), int(bool(corrected)),
                     GLOSS[int(truth)] if truth is not None else None, int(n_frames), float(lm_ms), float(model_ms)))


