def say(en, hi=None, interrupt=False):
    """Speak in the viewer's browser (instant) or on the server. Safe to call from inside the camera loop."""
    en = (en or "").strip(); hi = (hi or "").strip()
    if not en and not hi:
        return
    parts = []
    if speech_lang in ("English", "Both") and en:
        parts.append((en, "en-IN"))
    if speech_lang in ("Hindi", "Both") and hi:
        parts.append((hi, "hi-IN"))
    if not parts:
        parts = [(en or hi, "en-IN")]
    if voice_mode.startswith("Server"):
        for text, lang in parts:
            if lang == "hi-IN" and not isl_core.can_speak_local("hi"):
                mp3 = isl_core.tts_mp3(text, "hi")
                if mp3:
                    SPEECH.audio(mp3, format="audio/mp3", autoplay=True)
                    continue
                text, lang = en, "en-IN"
            isl_core.speak_english(text, lang[:2], voice_rate)
        return
    payload = json.dumps([{"text": t, "lang": l, "fallback": en} for t, l in parts])
    opts = json.dumps({"rate": voice_rate, "interrupt": bool(interrupt)})
    with SPEECH.container():
        components.html(f"<script>/* {uuid.uuid4().hex} */\n{SPEECH_JS.replace('__ITEMS__', payload).replace('__OPTS__', opts)}</script>", height=0)


def sentence():
    """Current transcript -> composed sentence dict (offline engine, optionally polished by Claude)."""
    out = isl_lang.compose(ss["words"], HINDI_OF)
    pol = ss.get("polished")
    if pol and pol.get("for") == list(ss["words"]):
        out = dict(out, en=pol["en"], hi=pol.get("hi", out["hi"]), polished=True)
    return out


