# ---------------------------------------------------------------------------------------------- page: learn & practice
def record_practice(target, probs, source, attempt_base):
    score = float(probs[target])
    top = int(np.argmax(probs))
    success = top == target and score >= 0.5
    gained = 0
    if success:
        ss["streak"] += 1; ss["best_streak"] = max(ss["best_streak"], ss["streak"])
        gained = 10 + 2 * min(ss["streak"] - 1, 10)
        ss["today_done"] += 1
        if KEYS[target] not in ss["mastered"]:
            ss["mastered"].append(KEYS[target]); gained += 15
    else:
        ss["streak"] = 0
        gained = 2 if score >= 0.25 else 1     # effort counts too
    ss["xp"] += gained
    di = demo_index()
    ref = DEMO_D["base"][di[target][0]] if target in di else None
    tips = isl_lang.coach_tips(ref, isl_core.segment_to_base(attempt_base)) if (ref is not None and not success) else []
    ss["practice_result"] = dict(target=target, score=score, top=top, success=success, gained=gained,
                                 msg=isl_lang.encouragement(score if top == target else min(score, 0.3)), tips=tips, t=time.time())
    STORE.write("INSERT INTO practice_attempts (sign_key, gloss, score, success, source) VALUES (%s,%s,%s,%s,%s)",
                "INSERT INTO practice_attempts (sign_key, gloss, score, success, source) VALUES (?,?,?,?,?)",
                (KEYS[target], GLOSS[target], score, success if STORE.kind == "postgres" else int(success), source))
    ss["say"] = (("Great job! " if success else "Try again. ") + GLOSS[target], None, True) if auto_speak else None


