if page == PAGES[4]:
    st.markdown("Upload a clip of **one or more signs**. SignSetu splits it into signs automatically, translates each one and builds "
                "the sentence. Frames are processed locally; the file is deleted right after.")
    up = st.file_uploader("Video", type=["mp4", "mov", "avi", "mkv", "webm"], key="uploader")
    if up is not None:
        cv_, cr_ = st.columns([2, 3])
        cv_.video(up)
        if cr_.button("Translate video", type="primary"):
            suffix = Path(up.name).suffix or ".mp4"
            tmp = tempfile.NamedTemporaryFile(delete=False, suffix=suffix)
            try:
                tmp.write(up.getbuffer()); tmp.close()
                cap = cv2.VideoCapture(tmp.name)
                total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
                vfps = float(cap.get(cv2.CAP_PROP_FPS) or 25.0) or 25.0
                if not cap.isOpened() or cap.read()[0] is False:
                    cr_.error("Could not decode this video. Try MP4 (H.264).")
                else:
                    cap.set(cv2.CAP_PROP_POS_FRAMES, 0)
                    ex = isl_core.LiveExtractor(); bases, actives, keyf = [], [], []
                    bar = cr_.progress(0.0, text="Extracting landmarks…"); t0 = time.perf_counter(); n = 0
                    try:
                        while True:
                            ok, fr = cap.read()
                            if not ok:
                                break
                            h, w = fr.shape[:2]; s = 640 / max(h, w)
                            if s < 1:
                                fr = cv2.resize(fr, (int(w * s), int(h * s)), interpolation=cv2.INTER_AREA)
                            rgb = cv2.cvtColor(cv2.flip(fr, 1), cv2.COLOR_BGR2RGB)
                            base, info, res = ex.process(rgb)
                            bases.append(base); actives.append(info["active"]); n += 1
                            if info["n_hands"] and n % 3 == 0:
                                keyf.append((n, draw_landmarks(rgb.copy(), res)))
                            if total and n % 5 == 0:
                                bar.progress(min(n / total, 1.0), text=f"Extracting landmarks… {n}/{total}")
                    finally:
                        ex.close(); cap.release(); bar.empty()
                    lm_ms = (time.perf_counter() - t0) * 1000
                    B = np.stack(bases) if bases else np.zeros((0, 252), np.float32)
                    has = (np.abs(B).sum(1) > 0) if len(B) else np.zeros(0, bool)
                    cov = float(has.mean()) if len(B) else 0.0
                    if has.sum() < 8:
                        cr_.warning("No sign detected — make sure your hands and face are clearly visible.")
                    else:
                        segm = isl_core.Segmenter(idle_end=max(6, int(round(vfps * 0.4))))
                        segs, start = [], None
                        for fi, (b, a) in enumerate(zip(B, actives)):
                            prev = segm.state
                            o = segm.update(b, a)
                            if prev == "IDLE" and segm.state == "SIGNING":
                                start = max(0, fi - 5)
                            if o is not None:
                                segs.append((start or 0, fi, o))
                        if segm.state == "SIGNING" and len(segm.buf) >= segm.min_len:
                            segs.append((start or 0, len(B) - 1, np.stack(segm.buf)))
                        if len(segs) <= 1:
                            segs = [(0, len(B) - 1, B)]
                        rows, keys_out = [], []
                        t1 = time.perf_counter()
                        for a, b, sg in segs:
                            probs = isl_core.focus_probs(PRED.predict_segment(sg), ALLOWED)
                            i = int(np.argmax(probs)); p = float(probs[i])
                            okw = i != REJ and p >= thr
                            if okw:
                                keys_out.append(KEYS[i])
                            rows.append({"from (s)": round(a / vfps, 2), "to (s)": round(b / vfps, 2), "sign": GLOSS[i],
                                         "hindi": HINDI[i], "confidence": round(p, 3), "used": "✓" if okw else "—"})
                            log_prediction("upload", probs, okw, len(sg), lm_ms / max(len(segs), 1), 0.0)
                        model_ms = (time.perf_counter() - t1) * 1000
                        s = isl_lang.compose(keys_out, HINDI_OF)
                        cr_.markdown(f"<div class='card'><div class='label'>Translation · {len(segs)} sign segment{'s' if len(segs) > 1 else ''}</div>"
                                     f"<div class='sentence'>{esc(s['en'] or 'No confident sign found')}</div>"
                                     f"<div class='sentence-hi hi'>{esc(s['hi'])}</div></div>", unsafe_allow_html=True)
                        cr_.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)
                        m1, m2, m3 = cr_.columns(3)
                        m1.metric("Decode + landmarks", f"{lm_ms/1000:.1f} s"); m2.metric("Model", f"{model_ms:.0f} ms"); m3.metric("Hand coverage", f"{cov*100:.0f}%")
                        if cov < 0.30:
                            cr_.warning("Hands were visible in less than 30% of the frames — the result may be unreliable.")
                        if s["en"]:
                            say(s["en"], s["hi"], interrupt=True)
                        if keyf:
                            pick = [keyf[int(k)] for k in np.linspace(0, len(keyf) - 1, 4)]
                            for col, (fi, img) in zip(st.columns(4), pick):
                                col.image(jpeg(img), caption=f"frame {fi}", use_container_width=True)
            finally:
                try:
                    os.unlink(tmp.name)
                except OSError:
                    pass


