@st.cache_data
def class_f1():
    if not CLASS_REPORT.exists():
        return {}
    d = pd.read_csv(CLASS_REPORT)
    gcol = next((c for c in d.columns if c.lower() in ("gloss", "class", "label")), d.columns[0])
    fcol = next((c for c in d.columns if c.lower() in ("f1", "f1-score", "f1_score")), None)
    return dict(zip(d[gcol].astype(str), d[fcol])) if fcol else {}


